sys_transform_script.script:
(function runTransformScript(source, map, log, target) {
    // Safety: never match without the partner record ID
    if (source.u_sender_sys_id.nil()) {
        error = true;
        error_message = 'Remote sync: u_sender_sys_id is empty, row rejected';
        return;
    }
    if (action == 'insert') {
        ignore = true;   // no linked customer Incident: the vendor may update, never create
        log.warn('Remote sync: no customer Incident linked to partner record ' + source.u_sender_sys_id);
    }
})(source, map, log, target);
